-- Shared module (shared.db)
-- Roles, approval trail, notifications, mail, audit and announcements.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE roles (
        key TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        description TEXT NOT NULL DEFAULT '',
        landing TEXT NOT NULL DEFAULT 'dashboard',
        is_system INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0, 1)),
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

CREATE TABLE role_permissions (
        role_key TEXT NOT NULL,
        module TEXT NOT NULL,
        PRIMARY KEY (role_key, module),
        FOREIGN KEY (role_key) REFERENCES roles(key) ON DELETE CASCADE
    );

CREATE TABLE role_permission_grants (
        role_key TEXT NOT NULL,
        permission TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 1 CHECK (allowed IN (0, 1)),
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (role_key, permission),
        FOREIGN KEY (role_key) REFERENCES roles(key) ON DELETE CASCADE
    );

CREATE TABLE hiring_role_permissions (
        role_key TEXT NOT NULL,
        right TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 1,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (role_key, right)
    );

CREATE TABLE hiring_user_permissions (
        user_id INTEGER NOT NULL,
        right TEXT NOT NULL,
        allowed INTEGER NOT NULL DEFAULT 1,
        granted_by INTEGER,
        updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (user_id, right));

CREATE TABLE approval_requests (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                request_type TEXT NOT NULL
                    CHECK (request_type IN (
                        'Purchase', 'Expense', 'Leave', 'Stock Adjustment',
                        'Payroll', 'Project', 'Other'
                    )),
                department TEXT NOT NULL
                    CHECK (department IN (
                        'hr', 'finance', 'payroll', 'inventory', 'procurement',
                        'production', 'sales', 'general'
                    )),
                amount REAL NOT NULL DEFAULT 0 CHECK (amount >= 0),
                description TEXT NOT NULL,
                created_by INTEGER NOT NULL,
                created_by_name TEXT NOT NULL,
                current_approver_step TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'Pending'
                    CHECK (status IN ('Pending', 'Approved', 'Rejected', 'Returned')),
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            , source_table TEXT, source_id INTEGER, approval_path TEXT NOT NULL DEFAULT '', updated_by INTEGER, updated_by_name TEXT);

CREATE TABLE approval_actions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                request_id INTEGER NOT NULL,
                actor_id INTEGER,
                actor_name TEXT NOT NULL,
                actor_role TEXT NOT NULL,
                action TEXT NOT NULL,
                comments TEXT DEFAULT '',
                action_at TEXT NOT NULL, step TEXT, previous_status TEXT,
                FOREIGN KEY (request_id) REFERENCES approval_requests(id)
                    ON DELETE CASCADE
            );

CREATE TABLE approval_routes (
        department TEXT PRIMARY KEY,
        first_step TEXT NOT NULL,
        updated_at TEXT
    );

CREATE TABLE management_approval_policy (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        manager_limit REAL NOT NULL,
        director_limit REAL NOT NULL,
        updated_by TEXT NOT NULL DEFAULT 'system',
        updated_at TEXT
    , pr_route_mode TEXT NOT NULL DEFAULT 'amount');

CREATE TABLE notifications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                category TEXT NOT NULL DEFAULT 'system',
                title TEXT NOT NULL,
                body TEXT DEFAULT '',
                href TEXT DEFAULT '',
                icon TEXT DEFAULT 'bell',
                tone TEXT DEFAULT 'neutral',
                dedupe_key TEXT,
                read_at TEXT,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE email_deliveries (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                recipient TEXT NOT NULL DEFAULT '',
                subject TEXT NOT NULL DEFAULT '',
                category TEXT NOT NULL DEFAULT 'system',
                event_key TEXT,
                status TEXT NOT NULL
                    CHECK (status IN ('Sent', 'Failed', 'Skipped')),
                error TEXT DEFAULT '',
                related_type TEXT,
                related_id TEXT,
                created_at TEXT NOT NULL,
                finished_at TEXT
            );

CREATE TABLE announcements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                body TEXT NOT NULL DEFAULT '',
                href TEXT DEFAULT '',
                audience TEXT NOT NULL DEFAULT 'all',
                created_by INTEGER,
                created_by_name TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );

CREATE TABLE audit_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                occurred_at TEXT NOT NULL,
                user_id TEXT,
                username TEXT NOT NULL,
                role TEXT NOT NULL,
                action TEXT NOT NULL,
                module TEXT NOT NULL,
                description TEXT NOT NULL,
                record_type TEXT,
                record_id TEXT,
                ip_address TEXT,
                outcome TEXT NOT NULL DEFAULT 'SUCCESS'
                    CHECK (outcome IN ('SUCCESS', 'FAILURE', 'DENIED')),
                details_json TEXT
            , full_name TEXT, department TEXT, device_type TEXT, os TEXT, browser TEXT, user_agent TEXT, previous_json TEXT, updated_json TEXT);

CREATE TABLE audit_activity (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                action TEXT NOT NULL,
                resource TEXT NOT NULL,
                record_id INTEGER,
                details TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE audit_reviews (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                department TEXT NOT NULL CHECK (
                    department IN (
                        'Finance', 'Budget', 'Inventory',
                        'Procurement', 'HR', 'Payroll'
                    )
                ),
                review_period_start TEXT,
                review_period_end TEXT,
                status TEXT NOT NULL DEFAULT 'Open'
                    CHECK (status IN (
                        'Open', 'In Progress', 'Completed'
                    )),
                summary TEXT DEFAULT '',
                created_by INTEGER NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE audit_findings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                review_id INTEGER NOT NULL,
                title TEXT NOT NULL,
                description TEXT NOT NULL,
                risk_level TEXT NOT NULL DEFAULT 'Medium'
                    CHECK (risk_level IN (
                        'Low', 'Medium', 'High', 'Critical'
                    )),
                source_table TEXT DEFAULT '',
                source_record_id INTEGER,
                recommendation TEXT DEFAULT '',
                status TEXT NOT NULL DEFAULT 'Open'
                    CHECK (status IN (
                        'Open', 'Under Review', 'Resolved', 'Closed'
                    )),
                management_response TEXT DEFAULT '',
                created_by INTEGER NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
                FOREIGN KEY (review_id)
                    REFERENCES audit_reviews(id));

CREATE INDEX idx_hiring_user_rights ON hiring_user_permissions (user_id);
CREATE INDEX idx_approval_creator
                ON approval_requests(created_by, created_at);
CREATE INDEX idx_approval_source ON approval_requests(source_table, source_id);
CREATE INDEX idx_approval_status ON approval_requests(status);
CREATE INDEX idx_approval_actions_request
                ON approval_actions(request_id);
CREATE INDEX idx_approval_actor ON approval_actions(request_id, action_at);
CREATE INDEX idx_notifications_created
                ON notifications(user_id, created_at);
CREATE UNIQUE INDEX idx_notifications_dedupe ON notifications(user_id, dedupe_key) WHERE dedupe_key IS NOT NULL;
CREATE INDEX idx_notifications_user ON notifications(user_id, read_at);
CREATE INDEX idx_email_delivery_event ON email_deliveries(recipient, event_key, status);
CREATE INDEX idx_email_delivery_time ON email_deliveries(finished_at);
CREATE INDEX idx_audit_action ON audit_logs(action);
CREATE INDEX idx_audit_department ON audit_logs(department);
CREATE INDEX idx_audit_device ON audit_logs(device_type);
CREATE INDEX idx_audit_ip ON audit_logs(ip_address);
CREATE INDEX idx_audit_module
                ON audit_logs(module, id DESC);
CREATE INDEX idx_audit_occurred_at ON audit_logs(occurred_at);
CREATE INDEX idx_audit_outcome
                ON audit_logs(outcome, occurred_at);
CREATE INDEX idx_audit_username ON audit_logs(username);
CREATE INDEX idx_audit_findings_review
                ON audit_findings(review_id);
CREATE INDEX idx_audit_findings_risk
                ON audit_findings(risk_level);

CREATE TRIGGER audit_logs_no_update
            BEFORE UPDATE ON audit_logs
            BEGIN
                SELECT RAISE(ABORT, 'audit_logs is append-only');
            END;

CREATE TRIGGER audit_logs_no_delete
            BEFORE DELETE ON audit_logs
            BEGIN
                SELECT RAISE(ABORT, 'audit_logs is append-only');
            END;
